        if (resortish) return true;
        return false;
      }
      if (hasToddler) {
        var toddlerOk = has('toddler_friendly') || has('young_kids') || has('family_all_ages');
        if (!toddlerOk) return false;
        if (has('teen_only') && !has('family_all_ages')) return false;
        return true;
      }
      if (hasTeen && !hasToddler) {
        return has('teen_thrills') || has('family_all_ages') || has('young_kids') || resortish;
      }
      if (hasYoungKid && !hasTeen) {
        if (has('teen_only')) return false;
        return has('toddler_friendly') || has('young_kids') || has('family_all_ages');
      }
      return true;
    }

