    function loadGooglePlacesApi() {
      if (state.placesReadyPromise) return state.placesReadyPromise;
      state.placesReadyPromise = new Promise(function (resolve, reject) {
        if (window.google && window.google.maps && window.google.maps.places) {
          state.placesReady = true;
          resolve(window.google);
          return;
        }
        if (!window.MatayGmapsFrugal) {
          reject(new Error('no-frugal'));
          return;
        }
        window.MatayGmapsFrugal.ensureGoogleMaps(function () {
          if (window.google && window.google.maps && window.google.maps.places) {
            state.placesReady = true;
            resolve(window.google);
          } else reject(new Error('google-load-failed'));
        });
      });
      return state.placesReadyPromise;
    }

    function ensurePlacesService() {
      if (state.placesService) return state.placesService;
      var div = document.createElement('div');
      div.style.cssText = 'width:1px;height:1px;position:absolute;left:-9999px;top:-9999px;';
      document.body.appendChild(div);
      var gm = new window.google.maps.Map(div, { center: { lat: 48.5, lng: 10.5 }, zoom: 5 });
      state.placesService = new window.google.maps.places.PlacesService(gm);
      return state.placesService;
    }

    function enrichParkFromGoogle(item) {
      if (!item || state.placesCache[item.id]) return Promise.resolve(state.placesCache[item.id] || null);
      if (window.MatayGmapsFrugal) {
        var disk = MatayGmapsFrugal.readThemeParkGoogle(item.id);
        if (disk) {
          state.placesCache[item.id] = disk;
          return Promise.resolve(disk);
        }
      }
      return loadGooglePlacesApi()
        .then(function () {
          var service = ensurePlacesService();
          return new Promise(function (resolve) {
            var q = item.park.name + ', ' + (item.countryName || '');
            service.textSearch({ query: q }, function (results, status) {
              if (status !== window.google.maps.places.PlacesServiceStatus.OK || !results || !results.length) {
                state.placesCache[item.id] = null;
                resolve(null);
                return;
              }
              var top = results[0];
              var photo = top.photos && top.photos[0] ? top.photos[0].getUrl({ maxWidth: 420, maxHeight: 260 }) : null;
              var priceMap = ['€', '€€', '€€€', '€€€€'];
              var price = (top.price_level != null && priceMap[top.price_level]) ? priceMap[top.price_level] : null;
              var out = {
                place_id: top.place_id || null,
                rating: top.rating != null ? Number(top.rating) : null,
                reviews_total: top.user_ratings_total != null ? Number(top.user_ratings_total) : null,
                price_level: price,
                photo_url: photo
              };
              state.placesCache[item.id] = out;
              if (window.MatayGmapsFrugal) MatayGmapsFrugal.writeThemeParkGoogle(item.id, out);
              resolve(out);
            });
          });
        })
