    function escapeHtml(t) {
      var d = document.createElement('div');
      d.textContent = t == null ? '' : String(t);
      return d.innerHTML;
    }
    function escapeAttr(t) {
      return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    }

    function stripQuotesForMatch(s) {
      return String(s || '').replace(/[\u2018\u2019\u02BC\u0027\u05F3`]/g, '');
    }

    function countrySearchMatches(countryQ, item) {
      if (!countryQ) return true;
      var cc = String(item.countryCode || '').toLowerCase();
      if (countryQ.length === 2 && cc === countryQ) return true;
      var cname = (item.countryName || '').toLowerCase().normalize('NFKC');
      var che = (COUNTRY_HE[item.countryCode] || '').toLowerCase().normalize('NFKC');
      var pname = String((item.park && item.park.name) || '').toLowerCase().normalize('NFKC');
      if (cname.indexOf(countryQ) !== -1 || che.indexOf(countryQ) !== -1 || pname.indexOf(countryQ) !== -1) return true;
      var qStrip = stripQuotesForMatch(countryQ);
      var cnStrip = stripQuotesForMatch(cname);
      var chStrip = stripQuotesForMatch(che);
      var pnStrip = stripQuotesForMatch(pname);
      if (qStrip && (cnStrip.indexOf(qStrip) !== -1 || chStrip.indexOf(qStrip) !== -1 || pnStrip.indexOf(qStrip) !== -1)) return true;
      return false;
    }

    /** Tag + kind rules for parent-facing filter chips (see european-theme-parks.json meta.tags_schema.family_filters). */
    function parkMatchesFamilyChip(mode, item) {
      if (!mode || mode === 'all') return true;
      var p = item.park;
      var tags = p.tags || [];
      var k = String(p.kind || '');
      function has(t) {
        return tags.indexOf(t) !== -1;
      }
      var lod = (p.visitor_extras && p.visitor_extras.lodging) || {};
      if (mode === 'hotel') return lod.sleep_inside_park_or_resort === true;
      if (mode === 'water') return has('water_park') || k.indexOf('water') !== -1;
      if (mode === 'resort') {
        var ins = lod.sleep_inside_park_or_resort === true;
        var kindR = k.indexOf('resort') !== -1;
        return ins || kindR || has('resort');
      }
      if (mode === 'toddlers') return has('toddler_friendly');
      if (mode === 'youngkids') {
        if (has('teen_only')) return false;
        return has('toddler_friendly') || has('young_kids') || has('family_all_ages');
      }
      if (mode === 'teens') return has('teen_thrills');
      if (mode === 'indoor') return has('indoor');
      if (mode === 'animals') {
        return has('animals_zoo') || has('dinosaurs') || k === 'theme_park_zoo' || k === 'marine_zoo_rides';
      }
      if (mode === 'learn') {
        return has('educational') || k === 'nature_edutainment' || k === 'science_media_park' || k === 'miniature_railway_park';
      }
      if (mode === 'shows') return has('shows_live') || k === 'show_park';
      return true;
    }

