    function shuffleInPlace(arr) {
      for (var i = arr.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
      }
      return arr;
    }

    /**
     * After family matching, the pool order follows the JSON (often many parks per country in a row).
     * Taking slice(0, N) therefore skews to one country. Prefer a random round-robin across countries,
     * then random within each country. If the user filtered to a single country, fall back to random there.
     */
    function pickRandomDiverseParksByCountry(items, cap) {
      if (!items || !items.length || cap == null || cap < 1) return items ? items.slice() : [];
      if (items.length <= cap) {
        var full = items.slice();
        shuffleInPlace(full);
        return full;
      }
      var byCountry = {};
      for (var i = 0; i < items.length; i++) {
        var it = items[i];
        var cc = it.countryCode || '_';
        if (!byCountry[cc]) byCountry[cc] = [];
        byCountry[cc].push(it);
      }
      var countries = Object.keys(byCountry);
      shuffleInPlace(countries);
      for (var c = 0; c < countries.length; c++) {
        shuffleInPlace(byCountry[countries[c]]);
      }
      if (countries.length === 1) {
        var only = byCountry[countries[0]].slice();
        shuffleInPlace(only);
        return only.slice(0, cap);
      }
      var out = [];
      var idx = {};
      while (out.length < cap) {
        var addedRound = false;
        var roundOrder = countries.slice();
        shuffleInPlace(roundOrder);
        for (var r = 0; r < roundOrder.length && out.length < cap; r++) {
          var cc2 = roundOrder[r];
          var list = byCountry[cc2];
          var pos = idx[cc2] || 0;
          if (pos < list.length) {
            out.push(list[pos]);
            idx[cc2] = pos + 1;
            addedRound = true;
          }
        }
        if (!addedRound) break;
      }
      return out;
    }

