          if (o && typeof o === 'object') {
            if (o.budgetBand) setFamilyBudgetRadioValue(o.budgetBand);
            if (o.resultLimit) setFamilyLimitRadioValue(o.resultLimit);
            if (o.ages && o.ages.length) {
