    function applyFilters() {
      syncSelectedFlagFromInput();
      var countryQ = (document.getElementById('countryFilter').value || '').trim().toLowerCase().normalize('NFKC');
      var chip = document.querySelector('.tp-chip[aria-pressed="true"]:not(:disabled)');
      var mode = chip && !chip.disabled ? chip.getAttribute('data-filter') : 'all';

      var quickSelected = document.querySelector('.tp-quick-chip[aria-pressed="true"]');
      var quickParkName = quickSelected ? String(quickSelected.getAttribute('data-park') || '').toLowerCase() : '';
      /** Spotlight is only the 4 hero parks - skip it when family matcher runs so matching uses the full list. */
      var familyPlannerOn = state.familyPlanner && state.familyPlanner.active;
      var browseSpotlight =
        !familyPlannerOn &&
        !state.hasUserInteracted &&
        !countryQ &&
        !quickParkName &&
        mode === 'all';

      if (browseSpotlight) {
        state.browseSpotlight = true;
        var order = SPOTLIGHT_PICKS.map(function (s) { return parkKey(s.code, s.name); });
        var byId = {};
        state.all.forEach(function (it) { byId[it.id] = it; });
        state.filtered = [];
        order.forEach(function (id) {
          if (byId[id]) state.filtered.push(byId[id]);
        });
      } else {
        state.browseSpotlight = false;
        state.filtered = state.all.filter(function (item) {
          if (state.selectedFlagCode && item.countryCode !== state.selectedFlagCode) return false;
          if (countryQ && !countrySearchMatches(countryQ, item)) return false;
          if (quickParkName && String(item.park.name || '').toLowerCase().indexOf(quickParkName) === -1) return false;
          return parkMatchesFamilyChip(mode, item);
        });
      }

      state.familyPlannerTotalMatched = 0;
      var preFamilyFilteredCount = state.filtered.length;
      if (state.familyPlanner && state.familyPlanner.active) {
        var fpp = state.familyPlanner;
        state.filtered = state.filtered.filter(function (item) {
          return parkPassesAgeGate(item, fpp.ages) && parkPassesBudgetGate(item, fpp.budgetBand);
        });
        state.familyPlannerTotalMatched = state.filtered.length;
        var sliceCap = getFamilyResultSliceCap();
        if (sliceCap != null && state.filtered.length > sliceCap) {
          state.filtered = pickRandomDiverseParksByCountry(state.filtered, sliceCap);
        }
      }

      state.filterCountBeforeFamily = preFamilyFilteredCount;
      state.shouldFitBounds = true;
      syncMap();
      renderCards();
      syncFlagStripPressed();
      writeThemeParksResultMeta();
    }

    function bindCardMapHover(cardsEl) {
      cardsEl.querySelectorAll('.tp-card[data-id]').forEach(function (card) {
        var id = card.getAttribute('data-id');
        card.addEventListener('mouseenter', function () { setMarkerHighlight(id, true); });
        card.addEventListener('mouseleave', function () { setMarkerHighlight(id, false); });
      });
    }

    function renderCards() {
      var skel = document.getElementById('skeletonWrap');
      var cards = document.getElementById('cardsWrap');
      var empty = document.getElementById('emptyState');
      var emptyHint = document.getElementById('emptyStateHint');
      var emptyTitle = document.getElementById('emptyStateTitle');
      var listHead = document.getElementById('listHead');
      var countryRaw = (document.getElementById('countryFilter').value || '').trim();
      skel.hidden = true;
      cards.hidden = false;
      if (state.filtered.length === 0) {
        cards.hidden = true;
        listHead.hidden = true;
        listHead.innerHTML = '';
        empty.hidden = false;
        if (emptyTitle) emptyTitle.textContent = 'לא נמצאו פארקים';
        if (emptyHint) {
          emptyHint.textContent =
            state.familyPlanner && state.familyPlanner.active
              ? 'נסו „ללא הגבלה” בתקציב, מסנן „הכל”, שינוי גילאים, או הרחבת חיפוש המדינה. אפשר גם „נקה” לביטול התאמת המשפחה.'
              : 'נסו שם מדינה אחר, או נקו את השדה ושינו את המסננים.';
        }
        cards.innerHTML = '';
        return;
      }
      var displayItems = getListDisplayItems();
      if (!displayItems.length && state.viewportListEnabled && !state.browseSpotlight) {
        cards.hidden = true;
        listHead.hidden = true;
        listHead.innerHTML = '';
        empty.hidden = false;
        if (emptyTitle) emptyTitle.textContent = 'אין פארקים בשטח המפה';
        if (emptyHint) emptyHint.textContent = 'הזיזו את המפה או התקרבו/התרחקו - או בטלו את „לפי שטח המפה” כדי לראות את כל הרשימה.';
        cards.innerHTML = '';
        return;
      }
      empty.hidden = true;
      if (!state.browseSpotlight && countryRaw) {
        var first = state.filtered[0];
        listHead.hidden = false;
        listHead.innerHTML = escapeHtml(first.countryFlag + ' ' + (COUNTRY_HE[first.countryCode] || first.countryName)) +
          '<span>' + state.filtered.length + ' פארקים במדינה זו</span>';
      } else {
        listHead.hidden = true;
        listHead.innerHTML = '';
      }
      cards.innerHTML = displayItems.map(cardHtml).join('');
      cards.querySelectorAll('[data-open-modal]').forEach(function (btn) {
        btn.addEventListener('click', function () { openModal(btn.getAttribute('data-open-modal')); });
      });
      bindCardMapHover(cards);
    }

    function onMapViewportChange() {
      updateEmbedMapResetVisibility();
      if (!state.map || state.browseSpotlight || !state.viewportListEnabled) return;
      if (state.viewportTimer) clearTimeout(state.viewportTimer);
      state.viewportTimer = setTimeout(function () {
        state.viewportTimer = null;
        renderCards();
        writeThemeParksResultMeta();
      }, 140);
    }

    function syncMap() {
      if (!state.map || !state.cluster) return;
      state.cluster.clearLayers();
      state.markers = {};
      var bounds = [];
      state.filtered.forEach(function (item) {
        var g = item.park.geo;
        if (!g || g.lat == null || g.lng == null) return;
        var narrowMap = typeof window.matchMedia === 'function' && window.matchMedia('(max-width: 960px)').matches;
        var m = L.marker([g.lat, g.lng], {
          icon: buildParkMarkerIcon(item, false),
          riseOnHover: !narrowMap
        });
        m._tpParkId = item.id;
        /* Always above the pin, shifted slightly to the screen-right (feels like „upper right” vs marker). keepInView pans the map so the card is not clipped. */
        m.bindTooltip(mapTooltipHtml(item), {
          direction: 'top',
          className: 'tp-map-tip',
          opacity: 1,
          interactive: false,
          sticky: true,
          keepInView: true,
          offset: L.point(20, -10)
        });
        m.on('tooltipopen', function () {
          m.setIcon(buildParkMarkerIcon(item, true));
          enrichParkFromGoogle(item).then(function () {
            var mk = state.markers[item.id];
            if (!mk) return;
            if (typeof mk.isTooltipOpen === 'function' && !mk.isTooltipOpen()) return;
            mk.setTooltipContent(mapTooltipHtml(item));
          });
        });
        m.on('tooltipclose', function () {
          m.setIcon(buildParkMarkerIcon(item, false));
        });
        m.on('click', function () {
          document.querySelectorAll('.tp-card').forEach(function (el) { el.classList.remove('tp-card--active'); });
          var sel = '[data-id="' + item.id.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"]';
          var ca = document.querySelector('.tp-card' + sel);
          if (ca) { ca.classList.add('tp-card--active'); ca.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); }
          openModal(item.id);
        });
        state.cluster.addLayer(m);
        state.markers[item.id] = m;
        bounds.push([g.lat, g.lng]);
      });
      if (bounds.length && state.shouldFitBounds) {
        state.map.fitBounds(bounds, { padding: [36, 36], maxZoom: 6 });
        state.shouldFitBounds = false;
      } else if (!bounds.length && state.map) {
        state.map.setView([50.5, 10.5], 4);
      }
      updateEmbedMapResetTarget(bounds);
      setTimeout(function () { onMapViewportChange(); }, 50);
    }

    function updateEmbedMapResetTarget(bounds) {
      if (bounds && bounds.length) state.embedResetBounds = L.latLngBounds(bounds);
      else state.embedResetBounds = null;
      updateEmbedMapResetVisibility();
    }

    function updateEmbedMapResetLabel() {
      var isEmbed = document.documentElement.classList.contains('tp-embed-map');
      var btn = state.embedResetButton || document.getElementById('tpMapResetHome');
      state.embedResetButton = btn;
      if (!btn) return;
      var label = 'חזור למפה הכללית';
      if (isEmbed) {
        var code = state.selectedFlagCode;
        var countryHe = (code && COUNTRY_HE[code]) ? COUNTRY_HE[code] : '';
        label = countryHe ? ('חזרה למפת ' + countryHe) : 'חזרה למפה המקורית';
      }
      btn.textContent = label;
      btn.setAttribute('aria-label', label);
    }

    function updateEmbedMapResetVisibility() {
      if (!state.map) return;
      var isEmbed = document.documentElement.classList.contains('tp-embed-map');
      var btn = state.embedResetButton || document.getElementById('tpMapResetHome');
      var actionsWrap = document.getElementById('tpMapActions');
      state.embedResetButton = btn;
      updateEmbedMapResetLabel();
      if (!btn) return;
      if (isEmbed && (!state.embedResetBounds || !state.embedResetBounds.isValid())) {
        if (actionsWrap) actionsWrap.hidden = true;
        return;
      }
      if (!isEmbed) {
        var showMain = state.map.getZoom() > 4;
        if (actionsWrap) actionsWrap.hidden = !showMain;
        return;
      }
      var current = state.map.getBounds();
      var movedAway = !current.pad(-0.08).contains(state.embedResetBounds);
      var zoomedIn = state.map.getZoom() > 6;
      var showEmbed = movedAway || zoomedIn;
      if (actionsWrap) actionsWrap.hidden = !showEmbed;
    }

    function initMap() {
      var isCoarsePointer = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
      state.map = L.map('tpMap', {
        scrollWheelZoom: false,
        zoomSnap: 0.5,
        zoomDelta: 0.5
      });
      L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
        maxZoom: 19,
        attribution: '&copy; OpenStreetMap contributors &copy; CARTO'
      }).addTo(state.map);
      if (typeof L.markerClusterGroup === 'function') {
        state.cluster = L.markerClusterGroup({
          showCoverageOnHover: false,
          maxClusterRadius: 56,
          spiderfyOnMaxZoom: true,
          disableClusteringAtZoom: 16,
          chunkedLoading: true
        }).addTo(state.map);
      } else {
        state.cluster = L.layerGroup().addTo(state.map);
      }
      state.map.setView([50.5, 10.5], 4);
      if (!isCoarsePointer) {
        state.map.once('click', function () { state.map.scrollWheelZoom.enable(); });
      } else {
        state.map.doubleClickZoom.disable();
        state.map.boxZoom.disable();
      }
      state.map.on('moveend', onMapViewportChange);
      state.map.on('zoomend', onMapViewportChange);
      var resetBtn = document.getElementById('tpMapResetHome');
      if (resetBtn) {
        state.embedResetButton = resetBtn;
        resetBtn.addEventListener('click', function () {
          var isEmbed = document.documentElement.classList.contains('tp-embed-map');
          if (isEmbed && state.map && state.embedResetBounds && state.embedResetBounds.isValid()) {
            state.map.fitBounds(state.embedResetBounds, { padding: [36, 36], maxZoom: 6 });
          } else if (state.map) {
            state.map.setView([50.5, 10.5], 4);
          }
        });
      }
    }

    function modalHoursHtml(schedule) {
      if (!schedule || !schedule.opening_periods || !schedule.opening_periods.length) {
        return '<div class="tp-modal__section tp-modal__section--flush"><div class="tp-modal__section-title">שעות</div><p class="tp-modal__hint">לפי עונה ואתר - לוודא בלוח הרשמי.</p></div>';
      }
      var bodyRows = schedule.opening_periods.slice(0, 4).map(function (period) {
        var lab = heScheduleLabel(period.label || 'תקופה');
        var op = period.opens || '-';
        var cl = period.closes || '-';
        var daysHe = heDaysToken(period.days) || '-';
        return '<tr><td>' + escapeHtml(lab) + '</td><td class="tp-modal__hours-time">' + escapeHtml(op) + ' – ' + escapeHtml(cl) + '</td><td>' + escapeHtml(daysHe) + '</td></tr>';
      }).join('');
      return '<div class="tp-modal__section tp-modal__section--flush">' +
        '<div class="tp-modal__section-title">שעות אופייניות</div>' +
        '<p class="tp-modal__hint tp-modal__hint--inline">דוגמאות מהלוח - המקור המעודכן בכפתור למעלה.</p>' +
        '<table class="tp-modal__hours-table" role="grid"><thead><tr><th scope="col">תקופה</th><th scope="col">שעות</th><th scope="col">ימים</th></tr></thead><tbody>' +
        bodyRows + '</tbody></table></div>';
