    function sectionVisitorExtrasCompact(vx) {
      if (!vx) return '';
      var lod = vx.lodging;
      var pk = vx.packages_with_park_entry;
      if (!lod && !pk) return '';
      var bits = [];
      if (lod) {
        if (lod.sleep_inside_park_or_resort === true) bits.push('לינה במתחם או ליד הכניסה - לפי האתר.');
        else if (lod.sleep_inside_park_or_resort === false) bits.push('ביקור יומי נפוץ; לינה באזור לפי האתר.');
        else bits.push('לינה: לעדכון באתר.');
      }
      if (pk) {
        if (pk.hotel_or_partner_bundles_include_park_tickets === true) bits.push('חבילות מלון+כניסה לעיתים קרובות.');
        else if (pk.hotel_or_partner_bundles_include_park_tickets === false) bits.push('כניסה כמעט תמיד בנפרד מלינה.');
      }
      if (!bits.length) return '';
      return '<div class="tp-modal__section tp-modal__section--flush"><div class="tp-modal__section-title">לינה וחבילות</div><p class="tp-modal__hint">' + bits.join(' ') + '</p></div>';
    }

    function buildStay22ThemeParkEmbedSrc(item) {
      if (!item || !item.park || !item.park.geo) return '';
      var lat = Number(item.park.geo.lat);
      var lng = Number(item.park.geo.lng);
      if (!isFinite(lat) || !isFinite(lng)) return '';
      var p = item.park;
      var venueBits = [p.name, p.location, item.countryName].filter(Boolean);
      var params = new URLSearchParams();
      if (STAY22_THEME_PARKS_AFFILIATE_ID) params.set('lmaID', STAY22_THEME_PARKS_AFFILIATE_ID);
      params.set('lat', String(lat));
      params.set('lng', String(lng));
      /* Map-only: hides hybrid list UI (incl. “list follows map viewport” toggle). See Stay22 map params. */
      params.set('viewmode', 'map');
      if (venueBits.length) params.set('venue', venueBits.join(', '));
      params.set('campaign', 'theme-parks');
      if (item.id) params.append('campaign', item.id);
      return 'https://www.stay22.com/embed/gm?' + params.toString();
    }

    function ingestLodgingStatic(data) {
      state.lodgingByParkId = (data && data.byParkId) ? data.byParkId : {};
    }

    function renderStaticLodgingCardsHtml() { return ''; }

