        '<div style="margin-top:8px;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;background:#fff;">' +
        '<iframe title="Stay22 - מלונות ליד ' + escapeAttr(parkName) + '" width="100%" height="320" src="' + escapeAttr(src) + '" frameborder="0" loading="lazy"></iframe>' +
        '</div>' +
