      var planHero = document.getElementById('tpModalPlanHero');
      if (planHero) planHero.innerHTML = modalPlanHeroHtml(p.name);
      var links = document.getElementById('tpModalLinks');
      var cta =
        '<p class="tp-modal__links-label">קישורים רשמיים</p><div class="tp-modal__cta-row">' +
        '<a href="' + escapeAttr(p.website) + '" class="tp-modal__btn tp-modal__btn--secondary" target="_blank" rel="noopener">לאתר הרשמי</a>';
      if (p.schedule && p.schedule.hours_url) {
        cta += '<a href="' + escapeAttr(p.schedule.hours_url) + '" class="tp-modal__btn tp-modal__btn--secondary" target="_blank" rel="noopener">לוח שנה ושעות</a>';
      }
      cta += '</div>';
      links.innerHTML = cta;
      var body = document.getElementById('tpModalBody');
      var parts = [];
      if (isWaterOrResortComingSoon(p)) {
        parts.push('<div class="tp-modal__soon-banner" role="status"><strong>פארק מים / ריזורט</strong> - מידע מורחב יתווסף בהמשך. עד אז: קישורים רשמיים למטה.</div>');
      }
      var pLevel = getPriceLevelLabel(item);
      var pDist = displayDistanceFromCity(p, item);
      parts.push('<div class="tp-modal__kpis">' +
        '<span class="tp-modal__kpi"><strong>דירוג</strong> · <span class="tp-modal__rating-row">' + ratingBlockHtml(p, id, true) + '</span></span>' +
        '<span class="tp-modal__kpi"><strong>סוג</strong> · ' + escapeHtml(KIND_HE[p.kind] || p.kind) + '</span>' +
        '<span class="tp-modal__kpi"><strong>עיר</strong> · ' + escapeHtml(p.location || '-') + '</span>' +
        '<span class="tp-modal__kpi"><strong>מחיר</strong> · ' + escapeHtml(pLevel) + '</span>' +
        '<span class="tp-modal__kpi"><strong>גישה</strong> · ' + escapeHtml(pDist) + '</span>' +
        '</div>');
      var xpModal = parkExperienceModalHtml(item);
