    });

    var TP_PLAN_WA = '972546758145';

    function buildTripPlanContext(opts) {
      opts = opts || {};
      var lines = ['היי, אני מעוניין/ת בתכנון טיול עם פארקי שעשועים באירופה.'];
      if (opts.parkName) lines.push('פארק שמעניין אותי: ' + opts.parkName);
      var countryElPlan = document.getElementById('countryFilter');
      var countryQ = countryElPlan ? String(countryElPlan.value || '').trim() : '';
      if (countryQ) lines.push('מדינה/אזור: ' + countryQ);
      var parkNames = [];
      if (opts.parkName) parkNames.push(opts.parkName);
      try {
        var items = getListDisplayItems();
        for (var i = 0; i < items.length && parkNames.length < 5; i++) {
          var n = items[i].park && items[i].park.name;
          if (n && parkNames.indexOf(n) === -1) parkNames.push(n);
        }
      } catch (e1) {}
      if (parkNames.length && !opts.parkName) {
        lines.push('ראיתי במפה: ' + parkNames.join(', '));
      }
      if (state.familyPlanner && state.familyPlanner.active && state.familyPlanner.ages && state.familyPlanner.ages.length) {
        lines.push('גילאי ילדים: ' + state.familyPlanner.ages.join(', '));
      }
      return { text: lines.join('\n') };
    }

    function resetTripPlanForm() {
      var formWrap = document.getElementById('tpPlanFormWrap');
      var success = document.getElementById('tpPlanSuccess');
      var form = document.getElementById('tpPlanForm');
      var submitBtn = document.getElementById('tpPlanSubmit');
      if (formWrap) formWrap.style.display = '';
      if (success) success.classList.remove('open');
      if (form) {
        form.reset();
        form.querySelectorAll('.error').forEach(function (el) { el.classList.remove('error'); });
      }
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.textContent = 'שלח פנייה';
      }
    }

    function openTripPlanPopup(opts) {
      opts = opts || {};
      var overlay = document.getElementById('tpPlanOverlay');
      if (!overlay) return;
      resetTripPlanForm();
      var ctx = buildTripPlanContext(opts);
      var msgEl = document.getElementById('tpPlanMessage');
      if (msgEl) msgEl.value = ctx.text;
      var waEl = document.getElementById('tpPlanWa');
      if (waEl) {
        waEl.href =
          'https://wa.me/' +
          TP_PLAN_WA +
          '?text=' +
          encodeURIComponent(ctx.text);
      }
      overlay.hidden = false;
      overlay.classList.add('open');
      document.body.style.overflow = 'hidden';
      if (opts.closeParkModal) closeModal();
      if (window.plausible) {
        try {
          plausible('ThemeParks-PlanPopup-Open', { props: { source: opts.source || 'unknown' } });
        } catch (e2) {}
      }
      var nameEl = document.getElementById('tpPlanName');
      if (nameEl) {
        try {
          nameEl.focus();
        } catch (e3) {}
      }
    }

    function closeTripPlanPopup() {
      var overlay = document.getElementById('tpPlanOverlay');
      if (!overlay || !overlay.classList.contains('open')) return;
      overlay.classList.remove('open');
      overlay.hidden = true;
      document.body.style.overflow = '';
    }

    function initTripPlanPopup() {
      var overlay = document.getElementById('tpPlanOverlay');
      if (!overlay) return;
      var closeBtn = document.getElementById('tpPlanClose');
      var form = document.getElementById('tpPlanForm');
      var submitBtn = document.getElementById('tpPlanSubmit');
      var waEl = document.getElementById('tpPlanWa');

      if (closeBtn) closeBtn.addEventListener('click', closeTripPlanPopup);
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) closeTripPlanPopup();
      });

      document.addEventListener('click', function (e) {
        var btn = e.target.closest('[data-plan-source]');
        if (!btn) return;
        e.preventDefault();
        e.stopPropagation();
        var source = btn.getAttribute('data-plan-source') || 'unknown';
        var parkName = btn.getAttribute('data-park-name') || '';
        openTripPlanPopup({
          source: source,
          parkName: parkName,
          closeParkModal: source === 'park-modal'
        });
      });

      if (waEl) {
        waEl.addEventListener('click', function () {
          if (window.plausible) {
            try {
              plausible('ThemeParks-PlanPopup-WA', { props: { page: 'theme-parks' } });
            } catch (e4) {}
          }
        });
      }

      if (form && submitBtn) {
        form.addEventListener('submit', function (e) {
          e.preventDefault();
          var nameEl = document.getElementById('tpPlanName');
          var phoneEl = document.getElementById('tpPlanPhone');
          var msgEl = document.getElementById('tpPlanMessage');
          var valid = true;
          [nameEl, phoneEl].forEach(function (f) {
            if (f) f.classList.remove('error');
          });
          if (!nameEl || !nameEl.value.trim()) {
            if (nameEl) nameEl.classList.add('error');
            valid = false;
          }
          if (!phoneEl || !phoneEl.value.trim()) {
            if (phoneEl) phoneEl.classList.add('error');
            valid = false;
          }
          if (!valid) return;

          submitBtn.disabled = true;
          submitBtn.textContent = 'שולח…';

          var formData = new FormData();
          formData.append('name', nameEl.value.trim());
          formData.append('phone', phoneEl.value.trim());
          formData.append('message', msgEl ? msgEl.value.trim() : '');
          formData.append('_subject', 'פנייה מתכנון טיול — פארקי שעשועים');

          fetch('https://formspree.io/f/__FORM_WEBSITE__', { method: 'POST', body: formData, headers: { Accept: 'application/json' } }).then(function (r) { if (!r.ok) throw new Error('form'); return r; })
            .then(function (r) { return r.json(); })
            .then(function () {
              var formWrap = document.getElementById('tpPlanFormWrap');
              var success = document.getElementById('tpPlanSuccess');
              if (formWrap) formWrap.style.display = 'none';
              if (success) success.classList.add('open');
              submitBtn.disabled = false;
              submitBtn.textContent = 'שלח פנייה';
              if (window.plausible) {
                try {
                  plausible('ThemeParks-PlanPopup-Submit', { props: { page: 'theme-parks' } });
                } catch (e5) {}
              }
            })
            .catch(function () {
              var subject = encodeURIComponent('פנייה מתכנון טיול — פארקי שעשועים');
              var body =
                'שם: ' +
                nameEl.value.trim() +
                '\nטלפון: ' +
                phoneEl.value.trim() +
                '\n\n' +
                (msgEl ? msgEl.value.trim() : '');
              window.location.href = 'mailto:info@mataytasim.co.il?subject=' + subject + '&body=' + encodeURIComponent(body);
              submitBtn.disabled = false;
              submitBtn.textContent = 'שלח פנייה';
              closeTripPlanPopup();
            });
        });
      }

      window.openTripPlanPopup = openTripPlanPopup;
    }

    initTripPlanPopup();

    function openLeadPopup() {
      var overlay = document.getElementById('tpLeadOverlay');
      if (!overlay) return;
      overlay.classList.add('open');
      document.body.style.overflow = 'hidden';
    }
    function closeLeadPopup() {
      var overlay = document.getElementById('tpLeadOverlay');
      if (!overlay) return;
      overlay.classList.remove('open');
      document.body.style.overflow = '';
    }

    document.querySelectorAll('.tp-chip').forEach(function (btn) {
      btn.addEventListener('click', function () {
        if (btn.getAttribute('data-coming-soon') === 'true') {
          openLeadPopup();
          return;
        }
        state.hasUserInteracted = true;
        deactivateFamilyPlannerForChipFilters();
        document.querySelectorAll('.tp-chip').forEach(function (b) {
          if (b.disabled) return;
          b.setAttribute('aria-pressed', b === btn ? 'true' : 'false');
        });
        applyFilters();
      });
    });
    var countryEl = document.getElementById('countryFilter');
    var quickChips = document.querySelectorAll('.tp-quick-chip');
    quickChips.forEach(function (chip) {
      chip.setAttribute('aria-pressed', 'false');
      chip.addEventListener('click', function () {
        state.hasUserInteracted = true;
        var nextState = chip.getAttribute('aria-pressed') !== 'true';
        quickChips.forEach(function (c) { c.setAttribute('aria-pressed', 'false'); });
        chip.setAttribute('aria-pressed', nextState ? 'true' : 'false');
        if (nextState) countryEl.value = '';
        applyFilters();
      });
    });
    document.querySelectorAll('.tp-inspo__img').forEach(function (img) {
      img.addEventListener('error', function () {
        var card = img.closest('.tp-inspo__card');
        if (card) card.classList.add('tp-inspo__card--img-fail');
      });
    });
    document.querySelectorAll('.tp-inspo__card').forEach(function (card) {
      card.addEventListener('click', function () {
        state.hasUserInteracted = true;
        var v = String(card.getAttribute('data-country-filter') || '').trim();
        if (!v) return;
        quickChips.forEach(function (c) { c.setAttribute('aria-pressed', 'false'); });
        countryEl.value = v;
        state.selectedFlagCode = '';
        for (var code in COUNTRY_HE) {
          if (Object.prototype.hasOwnProperty.call(COUNTRY_HE, code) && COUNTRY_HE[code] === v) {
            state.selectedFlagCode = code;
            break;
          }
        }
        if (filterDebounceTimer) {
          clearTimeout(filterDebounceTimer);
          filterDebounceTimer = null;
        }
        applyFilters();
        countryEl.focus();
      });
    });
    var filterDebounceTimer = null;
    function debouncedApplyFilters() {
      if (filterDebounceTimer) clearTimeout(filterDebounceTimer);
      filterDebounceTimer = setTimeout(function () {
        filterDebounceTimer = null;
        applyFilters();
      }, 180);
    }
    countryEl.addEventListener('input', function () {
      state.hasUserInteracted = true;
      quickChips.forEach(function (c) { c.setAttribute('aria-pressed', 'false'); });
      debouncedApplyFilters();
    });
    countryEl.addEventListener('change', function () {
      state.hasUserInteracted = true;
      if (filterDebounceTimer) clearTimeout(filterDebounceTimer);
      applyFilters();
    });
    var resetSearchBtn = document.getElementById('tpSearchReset');
    if (resetSearchBtn) {
      resetSearchBtn.addEventListener('click', function () {
        state.hasUserInteracted = true;
        deactivateFamilyPlannerForChipFilters();
        countryEl.value = '';
        state.selectedFlagCode = '';
        quickChips.forEach(function (c) { c.setAttribute('aria-pressed', 'false'); });
        document.querySelectorAll('.tp-chip').forEach(function (b) {
          if (b.disabled) return;
          b.setAttribute('aria-pressed', b.getAttribute('data-filter') === 'all' ? 'true' : 'false');
        });
        if (filterDebounceTimer) {
          clearTimeout(filterDebounceTimer);
          filterDebounceTimer = null;
        }
        applyFilters();
        countryEl.focus();
      });
    }

    var viewportCb = document.getElementById('tpViewportList');
    if (viewportCb) {
      viewportCb.checked = state.viewportListEnabled;
      viewportCb.addEventListener('change', function () {
        state.viewportListEnabled = !!viewportCb.checked;
        renderCards();
        writeThemeParksResultMeta();
      });
    }

    function refreshMapLayoutAfterResize() {
      if (!state.map) return;
      var delay = document.documentElement.classList.contains('tp-embed-map')
        ? 320
        : (window.innerWidth > 960 ? 120 : 220);
      setTimeout(function () {
        state.map.invalidateSize();
      }, delay);
    }
    window.addEventListener('resize', refreshMapLayoutAfterResize);
    var leadCloseBtn = document.getElementById('tpLeadClose');
    var leadOverlay = document.getElementById('tpLeadOverlay');
    if (leadCloseBtn) leadCloseBtn.addEventListener('click', closeLeadPopup);
    if (leadOverlay) {
      leadOverlay.addEventListener('click', function (e) {
        if (e.target === leadOverlay) closeLeadPopup();
      });
    }

    var navEl = document.getElementById('nav');
    var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
    var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
    if (hamburger && mobileMenu) {
      hamburger.addEventListener('click', function (e) {
        e.stopPropagation();
        var isOpen = mobileMenu.classList.toggle('open');
        hamburger.setAttribute('aria-expanded', isOpen.toString());
        hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
        document.body.style.overflow = isOpen ? 'hidden' : '';
      });
      mobileMenu.querySelectorAll('a').forEach(function (link) {
        link.addEventListener('click', function () {
          mobileMenu.classList.remove('open');
          hamburger.setAttribute('aria-expanded', 'false');
          hamburger.setAttribute('aria-label', 'פתח תפריט');
          document.body.style.overflow = '';
        });
      });
      document.addEventListener('keydown', function (e) {
        if (e.key !== 'Escape') return;
        if (!mobileMenu.classList.contains('open')) return;
        mobileMenu.classList.remove('open');
        hamburger.setAttribute('aria-expanded', 'false');
        hamburger.setAttribute('aria-label', 'פתח תפריט');
        document.body.style.overflow = '';
        hamburger.focus();
      });
    }
    if (navEl) {
      window.addEventListener('scroll', function () {
        navEl.classList.toggle('scrolled', window.scrollY > 10);
      });
    }

    renderSkeleton();
    initMap();
    refreshMapLayoutAfterResize();

    function showParkDataError(html) {
      state.loadError = true;
      state.all = [];
      document.getElementById('skeletonWrap').innerHTML = '<div class="tp-empty"><strong>שגיאת טעינה</strong><span>' + html + '</span></div>';
      document.getElementById('cardsWrap').hidden = true;
    }

    /** Optional URL filter: theme-parks.html?cc=AT or ?country=AT (ISO 3166-1 alpha-2, must exist in COUNTRY_HE). */
    function applyCountryPresetFromQuery() {
      try {
        var params = new URLSearchParams(window.location.search);
        var raw = (params.get('cc') || params.get('country') || '').trim().toUpperCase();
        if (!raw || raw.length !== 2) return;
        if (!Object.prototype.hasOwnProperty.call(COUNTRY_HE, raw)) return;
        var ce = document.getElementById('countryFilter');
        if (!ce) return;
        ce.value = COUNTRY_HE[raw];
        state.selectedFlagCode = raw;
        updateEmbedMapResetLabel();
        document.querySelectorAll('.tp-quick-chip').forEach(function (c) {
          c.setAttribute('aria-pressed', 'false');
        });
      } catch (e) {}
    }

    function ingestEmbedData(data) {
      state.all = flattenPayload(data);
      applyCountryPresetFromQuery();
      applyFilters();
      buildFlagStrip();
    }

    function ensureLodgingData() { return Promise.resolve(); }

    var embedded = typeof window.__EUROPEAN_THEME_PARKS__ !== 'undefined' ? window.__EUROPEAN_THEME_PARKS__ : null;
    try {
      delete window.__EUROPEAN_THEME_PARKS__;
    } catch (e) {}

    ensureLodgingData();

    initFamilyPlannerUi();

    if (embedded) {
      ingestEmbedData(embedded);
      refreshMapLayoutAfterResize();
    } else {
      fetch('european-theme-parks.json', { cache: 'no-cache' })
        .then(function (r) { if (!r.ok) throw new Error('bad'); return r.json(); })
        .then(function (data) {
          ingestEmbedData(data);
          refreshMapLayoutAfterResize();
        })
        .catch(function () {
          showParkDataError(
            'לא נמצא קובץ הנתונים המקומי (<code>european-theme-parks.embed.js</code>) ולא הצלחנו לטעון את <code>european-theme-parks.json</code>. ' +
            'ודאו ששני הקבצים נמצאים באותה תיקייה כמו דף זה, או הריצו <code>npm run build:parks-data</code> אחרי עדכון ה־JSON.'
          );
        });
    }
  })();
